//--------------------------------------------------------------------------------
// OiFlowCalibration — compact historical profile generated by OiFlowLab.
//
// Hub does not compute calibration online. It only caches the offline artifact,
// validates its schema and serves it to OiFlow together with the point-in-time
// market context.
//--------------------------------------------------------------------------------

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Net.Http;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace AvanpostHub
{
    public sealed class CalibrationStats
    {
        public int N { get; set; }
        public double? WinRate { get; set; }
        public double? WinRateLow95 { get; set; }
        public double? AvgRetPct { get; set; }
        public double? MedianRetPct { get; set; }
        public double? MfePct { get; set; }
        public double? MaePct { get; set; }
        public int Symbols { get; set; }
        public int Days { get; set; }
    }

    public sealed class CalibrationStateCell
    {
        public string Grade { get; set; } = "unrated";
        public string Reason { get; set; } = "";
        public CalibrationStats Development { get; set; } = new CalibrationStats();
        public CalibrationStats Confirmation { get; set; } = new CalibrationStats();
    }

    public sealed class CalibrationCohort
    {
        public Dictionary<string, CalibrationStateCell> States { get; set; } =
            new Dictionary<string, CalibrationStateCell>(StringComparer.OrdinalIgnoreCase);
    }

    public sealed class CalibrationStudyPeriod
    {
        public long StartMs { get; set; }
        public long EndMs { get; set; }
        public int Bars { get; set; }
        public int IndependentSignals { get; set; }
        public int N { get; set; }
        public double? WinRate { get; set; }
        public double? AvgRetPct { get; set; }
    }

    public sealed class CalibrationStudy
    {
        public CalibrationStudyPeriod Development { get; set; } = new CalibrationStudyPeriod();
        public CalibrationStudyPeriod Confirmation { get; set; } = new CalibrationStudyPeriod();
        public int Instruments { get; set; }
        public int Bars { get; set; }
        public int IndependentSignals { get; set; }
        public int GradedCells { get; set; }
    }

    public sealed class OiFlowCalibrationProfile
    {
        public const string ExpectedSchema = "avanpost.oi-flow-calibration.v1";

        public string Schema { get; set; } = "";
        public string GeneratedAt { get; set; } = "";
        public string Timeframe { get; set; } = "";
        public int HorizonBars { get; set; }
        public int LookbackBars { get; set; }
        public int CooldownBars { get; set; }
        public long SplitAtMs { get; set; }
        public CalibrationStudy Study { get; set; } = new CalibrationStudy();
        public Dictionary<string, string> InstrumentsByName { get; set; } =
            new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        public Dictionary<string, CalibrationCohort> Cohorts { get; set; } =
            new Dictionary<string, CalibrationCohort>(StringComparer.OrdinalIgnoreCase);
        public string[] Warnings { get; set; } = new string[0];

        public bool IsValid()
        {
            if (!string.Equals(Schema, ExpectedSchema, StringComparison.OrdinalIgnoreCase)) return false;
            if (string.IsNullOrWhiteSpace(Timeframe) || HorizonBars <= 0) return false;
            return Cohorts != null && Cohorts.Count > 0;
        }

        public string CohortFor(string instrument)
        {
            var symbol = Symbol(instrument);
            string cohort;
            if (symbol.Length > 0 && InstrumentsByName != null &&
                InstrumentsByName.TryGetValue(symbol, out cohort) && !string.IsNullOrWhiteSpace(cohort))
                return cohort.ToLowerInvariant();
            return "all";
        }

        public CalibrationStateCell Find(string instrument, string state)
        {
            if (string.IsNullOrWhiteSpace(state)) return null;
            var cohort = CohortFor(instrument);
            var cell = FindInCohort(cohort, state);
            return cell ?? FindInCohort("all", state);
        }

        private CalibrationStateCell FindInCohort(string cohort, string state)
        {
            CalibrationCohort block;
            if (Cohorts == null || !Cohorts.TryGetValue(cohort ?? "", out block) || block == null)
                return null;
            CalibrationStateCell cell;
            return block.States != null && block.States.TryGetValue(state, out cell) ? cell : null;
        }

        public long GeneratedAtMs()
        {
            DateTimeOffset parsed;
            return DateTimeOffset.TryParse(GeneratedAt, CultureInfo.InvariantCulture,
                DateTimeStyles.AssumeUniversal, out parsed) ? parsed.ToUnixTimeMilliseconds() : 0;
        }

        private static string Symbol(string instrument)
        {
            var value = (instrument ?? "").Trim().ToUpperInvariant();
            if (value.Length == 0) return "";
            var parts = value.Split(':');
            return parts.Length > 1 ? parts[1] : value;
        }
    }

    public sealed class OiFlowCalibrationStore
    {
        private readonly object _gate = new object();
        private readonly string _path;
        private OiFlowCalibrationProfile _profile;
        private string _error = "";

        public OiFlowCalibrationStore(string path = null)
        {
            _path = string.IsNullOrWhiteSpace(path) ? AppPaths.CalibrationFile : path;
            Reload();
        }

        public string PathOnDisk => _path;
        public event Action<OiFlowCalibrationProfile> Updated;

        public bool Available
        {
            get { lock (_gate) return _profile != null; }
        }

        public string LastError
        {
            get { lock (_gate) return _error; }
        }

        public OiFlowCalibrationProfile Profile
        {
            get { lock (_gate) return _profile; }
        }

        public OiFlowCalibrationProfile GetProfile()
        {
            lock (_gate) return _profile;
        }

        public bool Reload()
        {
            if (!File.Exists(_path))
            {
                lock (_gate)
                {
                    _profile = null;
                    _error = "calibration profile not found";
                }
                return false;
            }

            try
            {
                var json = File.ReadAllText(_path);
                var profile = HubJson.Deserialize<OiFlowCalibrationProfile>(json);
                if (profile == null || !profile.IsValid())
                    throw new InvalidDataException("invalid OI Flow calibration profile");
                lock (_gate)
                {
                    _profile = profile;
                    _error = "";
                }
                var handler = Updated;
                if (handler != null)
                {
                    try { handler(profile); }
                    catch (Exception ex) { HubLog.Warn("calibration subscriber failed: " + ex.Message); }
                }
                return true;
            }
            catch (Exception ex)
            {
                lock (_gate)
                {
                    _profile = null;
                    _error = ex.Message;
                }
                HubLog.Warn("calibration load failed: " + ex.Message);
                return false;
            }
        }

        public bool ReplaceFromJson(string json)
        {
            try
            {
                var profile = HubJson.Deserialize<OiFlowCalibrationProfile>(json);
                if (profile == null || !profile.IsValid())
                    throw new InvalidDataException("invalid OI Flow calibration profile");
                var directory = System.IO.Path.GetDirectoryName(_path);
                if (!string.IsNullOrWhiteSpace(directory)) Directory.CreateDirectory(directory);
                var tmp = _path + ".tmp";
                File.WriteAllText(tmp, json);
                File.Move(tmp, _path, true);
                lock (_gate)
                {
                    _profile = profile;
                    _error = "";
                }
                var handler = Updated;
                if (handler != null)
                {
                    try { handler(profile); }
                    catch (Exception ex) { HubLog.Warn("calibration subscriber failed: " + ex.Message); }
                }
                return true;
            }
            catch (Exception ex)
            {
                lock (_gate) _error = ex.Message;
                HubLog.Warn("calibration update failed: " + ex.Message);
                return false;
            }
        }
    }

    public sealed class ScreenerCalibrationClient : IDisposable
    {
        private readonly HttpClient _http = new HttpClient { Timeout = TimeSpan.FromSeconds(15) };
        private int _refreshing;

        public ScreenerCalibrationClient()
        {
            _http.DefaultRequestHeaders.UserAgent.ParseAdd("AvanpostHub/0.3");
        }

        public async Task<bool> RefreshAsync(string baseUrl, OiFlowCalibrationStore store,
            CancellationToken cancellationToken = default(CancellationToken))
        {
            if (store == null || Interlocked.Exchange(ref _refreshing, 1) != 0) return false;
            try
            {
                var root = (baseUrl ?? "").Trim().TrimEnd('/');
                if (root.Length == 0) root = "https://avanpost.io";
                using (var response = await _http.GetAsync(
                    root + "/api/indicator-calibration/oi-flow", cancellationToken).ConfigureAwait(false))
                {
                    if (!response.IsSuccessStatusCode) return false;
                    var json = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
                    return store.ReplaceFromJson(json);
                }
            }
            catch (OperationCanceledException) { return false; }
            catch (Exception ex)
            {
                HubLog.Warn("calibration refresh failed: " + ex.Message);
                return false;
            }
            finally
            {
                Interlocked.Exchange(ref _refreshing, 0);
            }
        }

        public void Dispose()
        {
            _http.Dispose();
        }
    }
}
